.ds{--p-bg:#ffffff;--p-surface:#f1f3f6;--p-high:#fafbfc;--p-hover:#e1e6ed;--p-row-active:#e5e9f2;--p-disabled:#dce1e8;--p-glass:#f6f8fbe8;--p-backdrop:#2c333d66;--p-tile:#f2f3f0;--p-tile-header:#f3f4f1;--p-image-well:#e7e9e4;--p-selected-surface:#e7f0eb;--p-ink:#2c333d;--p-muted:#59636f;--p-on-accent:#ffffff;--p-line:#c2cad5;--p-line-subtle:#cbd2dc;--p-control-border:#7b8592;--p-edge:#ffffff;--p-edge-soft:#ffffffa8;--p-accent:#303b48;--p-accent-hover:#25303d;--p-shade:#000;--p-highlight:#6153b5;--p-highlight-soft:#e2ddf3;--p-soft:#d3e8de;--p-mark:#ffbf63;--p-mark-hover:#ffd07b;--p-mark-alt:#9ad9aa;--p-error:#a3313e;--p-error-soft:#f9e8e9;--p-error-line:#d4a2a8;--p-success:#26614f;--p-success-soft:#e5f2eb;--p-success-line:#8fb8a5;--p-warning:#805719;--p-warning-soft:#f6efd9;--p-warning-line:#b9a16f;--p-font:Pretendard, sans-serif;--p-display-font:Outfit, Pretendard, sans-serif;--p-text-sm:13px;--p-text-md:16px;--p-text-lg:24px;--p-space-xs:8px;--p-space-sm:12px;--p-space-md:16px;--p-space-lg:24px;--p-space-xl:32px;--p-radius:24px;--p-control-radius:16px;--p-inner-radius:12px;--p-shadow:6px 7px 16px #bbc4d166, -5px -5px 14px #ffffffed;--p-raised:3px 4px 8px #b9c3d066, -3px -3px 8px #ffffffed;--p-inset:inset 3px 3px 6px #b7c1cf55, inset -3px -3px 6px #ffffffd9;--p-pressed:inset 3px 3px 6px #15222f60,inset -1px -1px 3px #ffffff18;--p-float:0 12px 32px #26394d26;--p-lift:0 3px 5px #24314526;--p-control-shadow:0 3px 5px #24314526,inset 0 1px 0 #ffffff24;--p-selected-shadow:0 2px 5px #24314526;--p-knob-shadow:0 1px 3px #26344726;--p-glass-shadow:0 8px 24px #38465e12;--p-dialog-shadow:0 24px 80px #26344740;--p-drop:0 10px 12px #24293616;--p-ring:inset 0 0 0 2px #24293610;--p-focus-glow:0 0 0 2px #ed667b33;}
.ds {
  color:var(--p-ink); background:var(--p-bg); font:var(--p-text-md)/1.5 var(--p-font);
  color-scheme:light; word-break:keep-all; overflow-wrap:anywhere; text-align:left;
}
.ds,.ds * { box-sizing:border-box; }
.ds [hidden] { display:none!important; }
.ds :is(h1,h2,h3,p,fieldset) { margin:0; }
.ds :is(button,input,select,textarea) { font:inherit; color:inherit; letter-spacing:inherit; }
.ds button { cursor:pointer; touch-action:manipulation; }
.ds button:disabled { cursor:not-allowed; }
.ds :is(button,input,select,textarea,a,[tabindex]):focus-visible { outline:3px solid var(--p-highlight); outline-offset:3px; }
.ds .ui-icon { display:inline-block; width:20px; height:20px; flex-shrink:0; vertical-align:middle; }
.ds .ds-demo-note { font-size:var(--p-text-sm); margin-top:var(--p-space-sm); min-height:20px; color:var(--p-muted); }
.ds .ds-surface { border:1px solid var(--p-line); border-radius:var(--p-radius); background:var(--p-surface); }
.ds .ds-surface[data-material="raised"] { box-shadow:var(--p-shadow); border-color:var(--p-edge); }
.ds .ds-surface[data-material="inset"] { box-shadow:var(--p-inset); background:var(--p-bg); }
.ds .ds-surface[data-material="glass"] { background:var(--p-high); box-shadow:var(--p-glass-shadow); }
@supports (backdrop-filter:blur(16px)) { .ds .ds-surface[data-material="glass"] { background:var(--p-glass); backdrop-filter:blur(16px); } }
@media(prefers-reduced-transparency:reduce) { .ds .ds-surface[data-material="glass"] { background:var(--p-high); backdrop-filter:none; } }
@media(prefers-reduced-motion:reduce) { .ds * { transition:none!important; animation:none!important; } }

.ds .ds-choices { display:grid; grid-template-columns:repeat(auto-fit,minmax(min(100%,170px),1fr)); gap:var(--p-space-lg); }
.ds .ds-choices fieldset,.ds .ds-radio-group { border:0; padding:0; min-width:0; }
.ds .ds-choices legend,.ds .ds-radio-group legend { font-size:14px; font-weight:600; margin-bottom:var(--p-space-sm); padding:0; }
.ds .ds-choice { display:flex; align-items:center; gap:var(--p-space-sm); min-height:44px; width:fit-content; padding-inline:4px; cursor:pointer; font-size:14px; }
.ds .ds-choice input { appearance:none; position:relative; margin:0; width:22px; height:22px; border:1.5px solid var(--p-control-border); border-radius:7px; background:var(--p-bg); box-shadow:var(--p-inset); cursor:inherit; flex-shrink:0; }
.ds .ds-choice input:checked,.ds .ds-choice input:indeterminate { background:var(--p-accent); border-color:var(--p-accent); box-shadow:none; }
.ds .ds-choice input[type="checkbox"]:checked::after { content:''; position:absolute; width:6px; height:10px; left:6px; top:2px; border:solid var(--p-on-accent); border-width:0 2px 2px 0; transform:rotate(45deg); }
.ds .ds-choice input:indeterminate::after { content:''; position:absolute; width:10px; height:2px; left:4px; top:8px; background:var(--p-on-accent); transform:none; border:0; }
.ds .ds-choice input[type="radio"] { border-radius:50%; }
.ds .ds-choice input[type="radio"]:checked::after { content:''; position:absolute; inset:5px; background:var(--p-on-accent); border-radius:50%; }
.ds .ds-choice:has(:disabled) { color:var(--p-muted); cursor:not-allowed; }
.ds .ds-choice input:disabled { opacity:1; background:var(--p-disabled); border-color:var(--p-line); box-shadow:none; }
.ds .ds-choice input:disabled::after { border-color:var(--p-muted); }
.ds .ds-choice input[type="radio"]:disabled::after { background:var(--p-muted); }
.ds .ds-choice .ds-switch { width:44px; height:26px; border-radius:24px; }
.ds .ds-switch::before { content:''; position:absolute; top:3px; left:3px; width:18px; height:18px; border-radius:50%; background:var(--p-muted); box-shadow:var(--p-knob-shadow); transition:left var(--p-duration); }
.ds .ds-choice input.ds-switch:checked::after { content:none; }
.ds .ds-switch:checked::before { left:21px; background:var(--p-on-accent); }
.ds .ds-switch:disabled::before { background:var(--p-muted); box-shadow:none; }
@media(forced-colors:active) {
  .ds .ds-choice input:not(.ds-switch) { appearance:auto; }
  .ds .ds-choice input:not(.ds-switch)::after { display:none; }
  .ds .ds-switch { border-color:ButtonText; }
  .ds .ds-switch::before { background:ButtonText; }
  .ds .ds-switch:checked { background:Highlight; }
  .ds .ds-switch:checked::before { background:HighlightText; }
}
/* looks: checkbox, radio and switch share the label hook .ds-choice[data-look]; checked keeps a mark or a moved thumb, never color alone */
.ds .ds-choice[data-look="card"] { min-width:200px; min-height:56px; padding:12px 16px; border:1px solid var(--p-line); border-radius:var(--p-control-radius); background:var(--p-bg); }
.ds .ds-choice[data-look="card"]:has(:checked) { border-color:var(--p-accent); box-shadow:inset 0 0 0 1px var(--p-accent); background:var(--p-high); font-weight:600; }
.ds .ds-radio-group:has(> .ds-choice[data-look="card"]) .ds-choice + .ds-choice { margin-top:var(--p-space-xs); }
.ds .ds-choice[data-look="chip"] { gap:6px; min-height:44px; padding:8px 16px; border:1px solid var(--p-control-border); border-radius:99px; background:var(--p-bg); }
.ds .ds-choice[data-look="chip"] input { width:0; height:18px; border:0; background:transparent; box-shadow:none; }
.ds .ds-choice[data-look="chip"]:has(:focus-visible) { outline:3px solid var(--p-highlight); outline-offset:3px; }
.ds .ds-choice[data-look="chip"]:has(:checked) { padding-left:12px; border-color:var(--p-accent); background:var(--p-accent); color:var(--p-on-accent); }
.ds .ds-choice[data-look="chip"] input:checked { width:18px; background:transparent; }
.ds .ds-choice[data-look="chip"] input[type="checkbox"]:checked::after { left:6px; top:1px; border-color:var(--p-on-accent); }
.ds .ds-choice[data-look="list"] { width:100%; flex-direction:row-reverse; justify-content:space-between; min-height:52px; padding:12px 4px; border-block:1px solid var(--p-line); }
.ds .ds-radio-group:has(> .ds-choice[data-look="list"]) .ds-choice + .ds-choice { border-top:0; }
.ds .ds-radio-group:has(> .ds-choice[data-look="segment"]) { display:flex; flex-wrap:wrap; }
.ds .ds-radio-group:has(> .ds-choice[data-look="segment"]) > legend { width:100%; }
.ds .ds-choice[data-look="segment"] { position:relative; gap:6px; min-height:44px; margin:0; padding:10px 18px; border:1px solid var(--p-control-border); background:var(--p-bg); }
.ds .ds-choice[data-look="segment"] + .ds-choice[data-look="segment"] { margin-left:-1px; }
.ds .ds-choice[data-look="segment"]:first-of-type { border-radius:12px 0 0 12px; }
.ds .ds-choice[data-look="segment"]:last-of-type { border-radius:0 12px 12px 0; }
.ds .ds-choice[data-look="segment"] input { position:absolute; inset:0; width:100%; height:100%; opacity:0; }
.ds .ds-choice[data-look="segment"]:has(:checked) { z-index:1; border-color:var(--p-accent); background:var(--p-accent); color:var(--p-on-accent); font-weight:600; }
.ds .ds-choice[data-look="segment"]:has(:checked)::before { content:'✓'; content:'✓' / ''; }
.ds .ds-choice[data-look="segment"]:has(:focus-visible) { z-index:2; outline:3px solid var(--p-highlight); outline-offset:2px; }
.ds .ds-choice[data-look="text"] .ds-switch { width:64px; height:30px; }
.ds .ds-choice[data-look="text"] .ds-switch::before { width:22px; height:22px; top:2.5px; left:3px; }
.ds .ds-choice[data-look="text"] .ds-switch:checked::before { left:36px; }
.ds .ds-choice[data-look="text"] input.ds-switch::after,.ds .ds-choice[data-look="text"] input.ds-switch:checked::after { content:'끔'; content:'끔' / ''; position:absolute; top:50%; left:auto; right:9px; width:auto; height:auto; border:0; transform:translateY(-50%); color:var(--p-muted); font-size:11px; font-weight:700; line-height:1; }
.ds .ds-choice[data-look="text"] input.ds-switch:checked::after { content:'켬'; content:'켬' / ''; left:10px; right:auto; color:var(--p-on-accent); }
.ds .ds-choice[data-look]:has(:disabled) input:disabled { background:var(--p-disabled); border-color:var(--p-line); box-shadow:none; }
.ds .ds-choice[data-look]:has(:disabled) input:disabled::after { border-color:var(--p-muted); color:var(--p-muted); }
.ds .ds-choice[data-look]:has(:disabled) input:is([type="radio"],:indeterminate):disabled::after { background:var(--p-muted); }
.ds .ds-choice[data-look]:has(:disabled) input.ds-switch:disabled::before { background:var(--p-muted); box-shadow:none; }
.ds .ds-choice:is([data-look="chip"],[data-look="segment"],[data-look="card"]):has(:disabled) { border-color:var(--p-line); background:var(--p-disabled); color:var(--p-muted); box-shadow:none; }

'use client';
import React, { useEffect, useRef } from 'react';
export function Checkbox({ children, look, indeterminate = false, ...props }) {
  const ref = useRef(null);
  useEffect(() => { ref.current.indeterminate = indeterminate; }, [indeterminate]);
  return <label className="ds-choice" data-look={look}><input {...props} ref={ref} type="checkbox" />{children}</label>;
}

